package com.swapp.mail;

import java.time.Duration;

import org.springframework.stereotype.Component;
import org.springframework.web.util.HtmlUtils;

import com.swapp.config.SiteProperties;

/**
 * Builds the account emails. Every email has a plain-text part and a simple, table-free HTML part. User-supplied
 * text (display names) is HTML-escaped; links are generated by the server from {@link SiteProperties#publicUrl()}.
 */
@Component
public class AccountEmails {

    private final SiteProperties site;

    public AccountEmails(SiteProperties site) {
        this.site = site;
    }

    public EmailMessage verifyEmail(String to, String name, String token, Duration ttl) {
        String link = site.link("/verify-email.html#token=" + token);
        return build(to, "Confirm your email address", "verify-email", name,
                "Welcome to Swapp! Please confirm that this is your email address so you can start listing, "
                        + "offering and messaging.",
                "Confirm email address", link,
                "This link expires in " + human(ttl) + ". If you didn't create a Swapp account, you can ignore "
                        + "this email.");
    }

    public EmailMessage passwordReset(String to, String name, String token, Duration ttl) {
        String link = site.link("/reset-password.html#token=" + token);
        return build(to, "Reset your Swapp password", "password-reset", name,
                "We received a request to reset the password for your Swapp account.",
                "Choose a new password", link,
                "This link expires in " + human(ttl) + " and can be used once. If you didn't ask for this, you can "
                        + "ignore this email: your password stays the same.");
    }

    public EmailMessage passwordChanged(String to, String name) {
        return build(to, "Your Swapp password was changed", "password-changed", name,
                "The password for your Swapp account was just changed, and you were signed out on your other "
                        + "devices.",
                null, null,
                "If this wasn't you, reset your password straight away at " + site.link("/forgot-password.html")
                        + " and contact us at " + site.contactEmail() + ".");
    }

    /** Security alert: a provider account (e.g. Google) can now sign in to this Swapp account. */
    public EmailMessage signInMethodAdded(String to, String name, String provider, String providerEmail) {
        return build(to, provider + " sign-in was added to your Swapp account", "sign-in-added", name,
                "The " + provider + " account " + providerEmail + " can now be used to sign in to your Swapp "
                        + "account.",
                null, null,
                "If this wasn't you, reset your password at " + site.link("/forgot-password.html")
                        + ", disconnect " + provider + " in Settings and contact us at " + site.contactEmail() + ".");
    }

    public EmailMessage signInMethodRemoved(String to, String name, String provider) {
        return build(to, provider + " sign-in was removed from your Swapp account", "sign-in-removed", name,
                "Your " + provider + " account can no longer be used to sign in to Swapp. You can still sign in "
                        + "with your email and password.",
                null, null,
                "If this wasn't you, reset your password at " + site.link("/forgot-password.html")
                        + " and contact us at " + site.contactEmail() + ".");
    }

    public EmailMessage accountDeleted(String to, String name) {
        return build(to, "Your Swapp account has been deleted", "account-deleted", name,
                "As you asked, your Swapp account has been deleted. Your profile, listings, photos and "
                        + "notifications have been erased, and you have been signed out everywhere. Messages you sent "
                        + "remain visible to the people you sent them to, shown as from \"Deleted member\".",
                null, null,
                "If you didn't do this, contact us straight away at " + site.contactEmail() + ". You are welcome "
                        + "to join again at any time with the same email address.");
    }

    public EmailMessage accountSuspended(String to, String name, String reason) {
        return build(to, "Your Swapp account has been suspended", "account-suspended", name,
                "Your Swapp account has been suspended by our moderators for breaking the community guidelines. "
                        + "Reason: " + reason,
                null, null,
                "Your listings are hidden and you can't sign in while the suspension lasts. If you think this is "
                        + "a mistake, reply to " + site.contactEmail() + " and we will review it.");
    }

    public EmailMessage accountReinstated(String to, String name) {
        return build(to, "Your Swapp account has been restored", "account-reinstated", name,
                "Good news: your Swapp account has been restored and you can sign in again. Your listings were "
                        + "hidden during the suspension; mark them available again from My listings when you're ready.",
                "Sign in", site.link("/login.html"),
                "Please keep to the community guidelines in our Terms: " + site.link("/terms.html"));
    }

    public EmailMessage listingRemoved(String to, String name, String title, String note) {
        return build(to, "Your listing was removed", "listing-removed", name,
                "Our moderators removed your listing \"" + title + "\" because it broke the community guidelines."
                        + (note == null ? "" : " Note from the moderator: " + note),
                null, null,
                "Please review the guidelines in our Terms (" + site.link("/terms.html") + "). Questions? Contact "
                        + site.contactEmail() + ".");
    }

    // ---------------------------------------------------------------- layout

    EmailMessage build(String to, String subject, String kind, String name, String intro, String buttonText,
                       String link, String footnote) {
        String greeting = "Hi " + name + ",";
        StringBuilder text = new StringBuilder(greeting).append("\n\n").append(intro).append("\n\n");
        if (link != null) {
            text.append(buttonText).append(":\n").append(link).append("\n\n");
        }
        text.append(footnote).append("\n\n— The Swapp team\n").append(site.publicUrl());

        StringBuilder html = new StringBuilder()
                .append("<!doctype html><html><body style=\"margin:0;padding:24px;background:#f5f7f6;")
                .append("font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1d2b25\">")
                .append("<div style=\"max-width:520px;margin:0 auto;background:#ffffff;border-radius:12px;")
                .append("padding:32px\">")
                .append("<div style=\"font-size:20px;font-weight:800;color:#0f766e;margin-bottom:24px\">Swapp</div>")
                .append("<p style=\"margin:0 0 16px\">").append(esc(greeting)).append("</p>")
                .append("<p style=\"margin:0 0 24px;line-height:1.5\">").append(esc(intro)).append("</p>");
        if (link != null) {
            html.append("<p style=\"margin:0 0 24px\"><a href=\"").append(esc(link))
                    .append("\" style=\"display:inline-block;background:#0f766e;color:#ffffff;text-decoration:none;")
                    .append("font-weight:600;padding:12px 20px;border-radius:8px\">").append(esc(buttonText))
                    .append("</a></p>")
                    .append("<p style=\"margin:0 0 24px;font-size:13px;color:#5b6b64;word-break:break-all\">")
                    .append("Or paste this link into your browser:<br>").append(esc(link)).append("</p>");
        }
        html.append("<p style=\"margin:0;font-size:13px;line-height:1.5;color:#5b6b64\">").append(esc(footnote))
                .append("</p></div></body></html>");
        return new EmailMessage(to, subject, text.toString(), html.toString(), kind);
    }

    private static String esc(String s) {
        return HtmlUtils.htmlEscape(s);
    }

    static String human(Duration d) {
        if (d.toDays() >= 1 && d.toHoursPart() == 0) {
            return d.toDays() == 1 ? "24 hours" : d.toDays() + " days";
        }
        if (d.toHours() >= 1 && d.toMinutesPart() == 0) {
            return d.toHours() == 1 ? "1 hour" : d.toHours() + " hours";
        }
        return d.toMinutes() + " minutes";
    }
}
